// ─── Parse ERPNext Stock Update ──────────────────────────────────
// ERPNext sends the full document when a Stock Entry or Purchase
// Receipt is submitted. We extract the item codes and quantities.

const doc = $input.first().json;

// ERPNext Stock Entry has items in doc.items
const items = (doc.items || []).map(item => ({
  item_code: item.item_code,
  item_name: item.item_name,
  qty: item.qty || 0,
  warehouse: item.t_warehouse || item.warehouse,
  stock_entry_type: doc.stock_entry_type,
  doctype: doc.doctype,
}));

console.log(`[Phase 2] ERPNext stock update: ${items.length} item(s)`);
items.forEach(i => console.log(`  ${i.item_code}: qty ${i.qty} → ${i.warehouse}`));

return items.map(item => ({ json: item }));

// ─── Extract Medusa variant and prepare stock update ─────────────
const prevItem = $('Parse Stock Update').first().json;
const searchResult = $input.first().json;
const products = searchResult.products || [];

if (products.length === 0) {
  console.log(`[Phase 2] No Medusa product found for SKU: ${prevItem.item_code}`);
  return [{ json: { ...prevItem, medusa_found: false } }];
}

const product = products[0];
// Find the variant matching the SKU
const variant = (product.variants || []).find(v => v.sku === prevItem.item_code)
  || (product.variants || [])[0];

console.log(`[Phase 2] Found Medusa product: ${product.id}, variant: ${variant?.id}`);

return [{
  json: {
    ...prevItem,
    medusa_found: true,
    medusa_product_id: product.id,
    medusa_variant_id: variant?.id,
    new_quantity: prevItem.qty,
  }
}];
